import type { ConfigSectionProps } from './config_section_props'
import { ConfigSectionLayout } from './config_section_layout'
import { worktreeService } from '../../services/project/worktree_service'
import { WorktreeConfigList } from './worktree_config_list'

const PROJECT_CONFIG_SECTION_ID = 'project'
const PROJECT_CONFIG_SECTION_LABEL = 'Project'

interface ProjectConfigSectionProps extends ConfigSectionProps {
    disabled?: boolean
}

export function ProjectConfigSection(props: ProjectConfigSectionProps) {
    const { disabled = false, draft, entries, onChange, onValidityChange } = props
    const sectionEntries = entries.filter((entry) => entry.section === PROJECT_CONFIG_SECTION_ID)

    return (
        <>
            <ConfigSectionLayout
                disabled={disabled}
                draft={draft}
                entries={sectionEntries}
                id={PROJECT_CONFIG_SECTION_ID}
                label={PROJECT_CONFIG_SECTION_LABEL}
                onChange={onChange}
                onValidityChange={onValidityChange}
            />
            {worktreeService.isSupported() && !disabled ? <WorktreeConfigList /> : null}
        </>
    )
}

import { Box, CircularProgress, IconButton, Stack, Tooltip, Typography } from '@mui/material'
import Plus from 'mdi-material-ui/Plus'
import { useState } from 'react'
import type { WorktreeRecord } from '../../data/data_types'
import { useWorktreeAdding, useWorktrees } from '../hooks/use_worktrees'
import { dialogService } from '../../services/dialog_service'
import { worktreeService } from '../../services/project/worktree_service'
import { WorktreeConfigRow } from './worktree_config_row'
import { WorktreeRemoveDialog } from './worktree_remove_dialog'

export function WorktreeConfigList() {
    const worktrees = useWorktrees()
    const isAdding = useWorktreeAdding()
    const [removeRecord, setRemoveRecord] = useState<WorktreeRecord | null>(null)

    const handleAdd = async () => {
        try {
            await worktreeService.add()
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Worktree creation failed' })
        }
    }

    const handleRemove = (index: number) => {
        try {
            const record = worktrees[index]
            if (!record) throw new Error(`Invalid worktree list index: ${index}`)

            setRemoveRecord(record)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Worktree removal could not be opened' })
        }
    }

    const handleRemoveClose = () => {
        setRemoveRecord(null)
    }

    const handleRemoveConfirm = async () => {
        try {
            if (!removeRecord) throw new Error('Missing worktree removal target')
            const index = worktrees.findIndex(({ path }) => path === removeRecord.path)
            if (index === -1) throw new Error('Worktree removal target no longer exists')

            await worktreeService.remove(index)
            setRemoveRecord(null)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Worktree removal failed' })
        }
    }

    return (
        <Stack aria-label="Linked worktrees" spacing={1.25}>
            <Box>
                <Typography component="h3" variant="h6">Linked worktrees</Typography>
                <Typography color="text.secondary" variant="body2">
                    Add chooses an empty folder. Removing a worktree deletes its checkout folder but keeps its branch.
                </Typography>
            </Box>
            {worktrees.map((record, index) => (
                <WorktreeConfigRow index={index} key={`${index}-${record.path}`} onRemove={handleRemove} record={record} />
            ))}
            <Tooltip title="Add linked worktree">
                <IconButton aria-label="Add linked worktree" disabled={isAdding} onClick={handleAdd} size="small" sx={{ alignSelf: 'flex-start' }}>
                    {isAdding ? <CircularProgress aria-label="Creating linked worktree" size={24} /> : <Plus />}
                </IconButton>
            </Tooltip>
            <WorktreeRemoveDialog onClose={handleRemoveClose} onConfirm={handleRemoveConfirm} record={removeRecord} />
        </Stack>
    )
}

import { cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react'
import { afterEach, describe, expect, it, vi } from 'vitest'
import type { ProjectReference, StorageService, WorktreeRecord } from '../../data/data_types'
import { worktreeService } from '../../services/project/worktree_service'
import { createDeferred } from '../../services/test_support/data_service_test_support'
import { AppThemeProvider } from '../../theme/theme_provider'
import { WorktreeConfigList } from './worktree_config_list'

const project: ProjectReference = { branch: 'main', id: 'project', rootPath: 'C:\\primary' }
const first: WorktreeRecord = {
    branch: 'one', error: null, parkingBranch: 'md2/parking/one', path: 'C:\\one',
    status: { ahead: 0, baseAhead: 0, baseBehind: 0, behind: 0, dirty: false, hasUpstream: false }, valid: true,
}
const second: WorktreeRecord = {
    branch: 'two', error: null, parkingBranch: 'md2/parking/two', path: 'C:\\two',
    status: { ahead: 0, baseAhead: 0, baseBehind: 0, behind: 0, dirty: false, hasUpstream: false }, valid: true,
}

function initWorktreeService(storage: StorageService) {
    worktreeService.init({
        assignCardWorktree: vi.fn(),
        cardSeparatorProvider: () => '-',
        clearCardBranch: vi.fn(),
        flushPendingChanges: vi.fn(async () => undefined),
        projectFolderProvider: () => 'design',
        projectProvider: () => project,
        snapshotProvider: () => null,
        storageProvider: () => storage,
        unassignCardWorktree: vi.fn(),
    })
}

describe('WorktreeConfigList', () => {
    afterEach(() => {
        cleanup()
        worktreeService.clear()
    })

    it('adds and removes Git worktrees immediately', async () => {
        let callback: ((state: {
            error: null
            primaryStatus: null
            project: ProjectReference
            records: WorktreeRecord[]
        }) => void) | null = null
        const storage = {
            addWorktree: vi.fn(async () => {
                callback?.({ error: null, primaryStatus: null, project, records: [first, second] })
                return true
            }),
            onWorktreesChanged: vi.fn((listener) => {
                callback = listener
                listener({ error: null, primaryStatus: null, project, records: [first] })
                return vi.fn()
            }),
            removeWorktree: vi.fn(async () => callback?.({ error: null, primaryStatus: null, project, records: [second] })),
        } as unknown as StorageService
        initWorktreeService(storage)

        render(<AppThemeProvider><WorktreeConfigList /></AppThemeProvider>)
        expect(screen.getByText('C:\\one')).toBeInTheDocument()
        fireEvent.click(screen.getByRole('button', { name: 'Add linked worktree' }))
        expect(await screen.findByText('C:\\two')).toBeInTheDocument()

        fireEvent.click(screen.getByRole('button', { name: 'Remove worktree 1' }))
        expect(screen.getByText(/Git will remove the checkout folder C:\\one/u)).toBeInTheDocument()
        fireEvent.click(screen.getByRole('button', { name: 'Remove' }))

        await waitFor(() => expect(worktreeService.getRecords()).toEqual([second]))
        expect(storage.removeWorktree).toHaveBeenCalledWith(project, first.path)
    })

    it('shows progress while creating a Git worktree', async () => {
        const pendingAddition = createDeferred<boolean>()
        const storage = {
            addWorktree: vi.fn(() => pendingAddition.promise),
            onWorktreesChanged: vi.fn((listener) => {
                listener({ error: null, primaryStatus: null, project, records: [first] })
                return vi.fn()
            }),
        } as unknown as StorageService
        initWorktreeService(storage)

        render(<AppThemeProvider><WorktreeConfigList /></AppThemeProvider>)
        fireEvent.click(screen.getByRole('button', { name: 'Add linked worktree' }))

        expect(await screen.findByRole('progressbar', { name: 'Creating linked worktree' })).toBeInTheDocument()
        expect(screen.getByRole('button', { name: 'Add linked worktree' })).toBeDisabled()

        pendingAddition.resolve(true)
        await waitFor(() => expect(screen.queryByRole('progressbar', { name: 'Creating linked worktree' })).not.toBeInTheDocument())
    })
})

