const CONFIG_PAGE_PADDING = 3
const CONFIG_FORM_MAX_WIDTH = 720
const CONFIG_SIDEBAR_WIDTH = 220
const DRAFT_DISCARD_DELAY_MS = 0
const MARKDOWN_CONFIG_SECTION = { id: 'markdown', label: 'Markdown' }

interface MarkdownStyleDraft {
    config: MarkdownStyleConfig
    name: MarkdownStyleName
}

interface ConfigPageProps {
    hash: string
}

function getActiveSection(hash: string, sections: typeof CONFIG_SECTIONS) {
    if (sections.length === 0) return null

    const section = hash.replace('#', '')
    if (sections.some((item) => item.id === section)) return section

    return sections[0]?.id ?? null
}

function getVisibleSections(entries: ConfigEntry[]) {
    return CONFIG_SECTIONS.flatMap((section) => {
        const visibleSection = entries.some((entry) => entry.section === section.id) ? [section] : []
        return section.id === 'react' ? [...visibleSection, MARKDOWN_CONFIG_SECTION] : visibleSection
    })
}

function getConfigDraftSnapshot() {
    return configService.getDraft()
}

function subscribeToConfigChanges(onStoreChange: () => void) {
    configService.addEventListener('changed', onStoreChange)

    return () => configService.removeEventListener('changed', onStoreChange)
}

export function ConfigPage(props: ConfigPageProps) {
    const { hash } = props
    const theme = useTheme()
    const isMobile = useMediaQuery(theme.breakpoints.down('md'))
    const readOnly = useProjectReadOnly()
    const {
        markdownStyle,
        markdownStyleConfig,
        setCustomMarkdownStyle,
        setMarkdownStyle,
    } = useAppTheme()
    const draft = useSyncExternalStore(subscribeToConfigChanges, getConfigDraftSnapshot)
    const [invalidConfigKeys, setInvalidConfigKeys] = useState<Set<ConfigKey>>(() => new Set())
    const [isSaving, setIsSaving] = useState(false)
    const [markdownStyleDraft, setMarkdownStyleDraft] = useState<MarkdownStyleDraft>(() => ({
        config: cloneMarkdownStyleConfig(markdownStyleConfig),
        name: markdownStyle,
    }))
    const draftDiscardTimeoutRef = useRef<number | null>(null)
    const entries = configService.getEntries()
    const visibleSections = useMemo(() => getVisibleSections(entries), [entries])
    const activeSection = getActiveSection(hash, visibleSections)
    const markdownStyleChanged = markdownStyleDraft.name !== markdownStyle
        || JSON.stringify(markdownStyleDraft.config) !== JSON.stringify(markdownStyleConfig)
    const markdownStyleValid = isMarkdownStyleConfig(markdownStyleDraft.config)

    useEffect(() => {
        if (visibleSections.length === 0) dialogService.error('Config page requires at least one visible section')
    }, [visibleSections.length])

    useEffect(() => {
        if (draftDiscardTimeoutRef.current !== null) {
            window.clearTimeout(draftDiscardTimeoutRef.current)
            draftDiscardTimeoutRef.current = null
        }

        const currentDraft = configService.getDraft()
        if (!currentDraft) configService.loadDraft()
        return () => {
            // React StrictMode mounts, unmounts, and remounts effects; delay discard so the remount can cancel it.
            draftDiscardTimeoutRef.current = window.setTimeout(() => {
                configService.discardDraft()
                draftDiscardTimeoutRef.current = null
            }, DRAFT_DISCARD_DELAY_MS)
        }
    }, [])

    if (!draft) return null

    const handleValueChange = (key: ConfigKey, value: unknown) => {
        try {
            if (
                key === 'project.cardSeparator'
                && value !== draft[key]
                && value !== configService.get('project.cardSeparator')
            ) {
                dialogService.warning(
                    'Saving this change will rename existing card files and update their IDs.',
                    { critical: true, title: 'Card files will be renamed' },
                )
            }
            configService.setDraftValue(key, value)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Invalid config value' })
        }
    }

    const handleValidityChange = (key: ConfigKey, valid: boolean) => {
        setInvalidConfigKeys((currentKeys) => {
            if (valid && !currentKeys.has(key)) return currentKeys
            if (!valid && currentKeys.has(key)) return currentKeys

            const nextKeys = new Set(currentKeys)
            if (valid) nextKeys.delete(key)
            else nextKeys.add(key)

            return nextKeys
        })
    }

    const handleMarkdownStyleChange = (name: MarkdownStyleName, config: MarkdownStyleConfig) => {
        setMarkdownStyleDraft({ config, name })
    }

    const handleSaveClick = async () => {
        setIsSaving(true)
        try {
            const shouldSaveProjectConfig = configService.hasDraftChangesForSource('project')
            const shouldSaveDesktopConfig = configService.hasDraftChangesForSource('desktop')
            const previousCardSeparator = configService.get('project.cardSeparator')
            const nextCardSeparator = draft['project.cardSeparator']
            const remoteControlBridge = getElectronRemoteControlBridge()
            const remoteControlPortChanged = configService.hasDesktopConfig()
                && configService.get('desktop.remoteControlPort') !== draft['desktop.remoteControlPort']
            const shouldRestartRemoteControl = remoteControlPortChanged
                && remoteControlBridge
                && (await remoteControlBridge.getStatus()).active
            const shouldUpdateCardSeparator = configService.hasProjectConfig()
                && previousCardSeparator !== nextCardSeparator
            if (shouldUpdateCardSeparator) {
                await dataService.projectLoading.updateCardSeparator(previousCardSeparator, nextCardSeparator)
            }
            if (shouldSaveDesktopConfig && configService.hasDesktopConfig()) {
                const persistedDesktopConfig = await saveDesktopConfigToHost(configService.getDraftDesktopValues())
                configService.replaceDesktopConfig(persistedDesktopConfig)
                await agentCapabilitiesService.reload()
            }
            configService.saveDraft()
            configService.loadDraft()
            if (markdownStyleChanged && markdownStyleDraft.name === 'custom') setCustomMarkdownStyle(markdownStyleDraft.config)
            else if (markdownStyleChanged && isMarkdownStylePresetName(markdownStyleDraft.name)) {
                setMarkdownStyle(markdownStyleDraft.name)
            }
            if (shouldSaveProjectConfig && configService.hasProjectConfig()) await dataService.projectLoading.saveProjectConfig()
            navigateTo('/')
            if (shouldRestartRemoteControl) {
                try {
                    await remoteControlBridge.stop()
                    await remoteControlBridge.start()
                } catch (error) {
                    dialogService.error(error, { fallbackMessage: 'Remote-control restart failed' })
                    return
                }
            }
            dialogService.success('Config saved')
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Config save failed' })
        } finally {
            setIsSaving(false)
        }
    }

    const handleCancelClick = () => {
        configService.discardDraft()
        navigateTo('/')
    }

    const sectionProps = {
        draft,
        entries,
        onChange: handleValueChange,
        onValidityChange: handleValidityChange,
    }

    const sectionTabs = (
        <Tabs
            aria-label="Config sections"
            orientation={isMobile ? 'horizontal' : 'vertical'}
            scrollButtons="auto"
            value={activeSection ?? false}
            variant="scrollable"
        >
            {visibleSections.map((section) => (
                <Tab component="a" href={`#/config/${section.id}`} key={section.id} label={section.label} value={section.id} />
            ))}
        </Tabs>
    )

    return (
        <Dialog
            aria-labelledby="config-dialog-title"
            fullScreen={isMobile}
            fullWidth
            maxWidth="lg"
            onClose={handleCancelClick}
            open
        >
            <DialogTitle id="config-dialog-title" sx={{ borderBottom: 1, borderColor: 'divider' }}>
                Config
            </DialogTitle>
            <DialogContent
                aria-label="Config dialog body"
                sx={{ display: 'flex', minHeight: 0, overflow: 'hidden', p: 0 }}
            >
                {!isMobile ? (
                    <Box
                        aria-label="Config section navigation"
                        component="nav"
                        sx={{ borderRight: 1, borderColor: 'divider', flexShrink: 0, minHeight: 0, overflow: 'auto', width: CONFIG_SIDEBAR_WIDTH }}
                        tabIndex={0}
                    >
                        {sectionTabs}
                    </Box>
                ) : null}
                <Box
                    aria-label="Config section content"
                    role="region"
                    sx={{ flex: 1, minHeight: 0, minWidth: 0, overflow: 'auto', p: CONFIG_PAGE_PADDING }}
                    tabIndex={0}
                >
                    <Stack spacing={3} sx={{ maxWidth: CONFIG_FORM_MAX_WIDTH }}>
                        {isMobile ? sectionTabs : null}

                        {activeSection === 'react' ? <ReactConfigSection {...sectionProps} /> : null}
                        {activeSection === 'markdown' ? (
                            <MarkdownConfigSection
                                config={markdownStyleDraft.config}
                                name={markdownStyleDraft.name}
                                onChange={handleMarkdownStyleChange}
                            />
                        ) : null}
                        {activeSection === 'project' ? <ProjectConfigSection {...sectionProps} disabled={readOnly} /> : null}
                        {activeSection === 'desktop' ? <DesktopConfigSection {...sectionProps} disabled={!configService.hasDesktopConfig()} /> : null}
                    </Stack>
                </Box>
            </DialogContent>
            <DialogActions sx={{ bgcolor: 'background.default', borderTop: 1, borderColor: 'divider' }}>
                <Button onClick={handleCancelClick} variant="outlined">
                    Cancel
                </Button>
                <Button disabled={isSaving || invalidConfigKeys.size > 0 || !markdownStyleValid} onClick={handleSaveClick} variant="contained">
                    Save
                </Button>
            </DialogActions>
        </Dialog>
    )
}

import { slugifyTitle } from '../../data/card_naming'
import type { CardSeparator } from '../../data/card_identifiers'
import { getElectronActionBridge, type WorktreeDiffResult } from '../../data/electron_action_bridge'
import type {
    Card,
    ProjectReference,
    ProjectSnapshot,
    StorageService,
    WorktreeRecord,
    WorktreeState,
    WorktreeStatus,
} from '../../data/data_types'
import { register } from '../service_injector'

interface WorktreeServiceDependencies {
    assignCardWorktree: (path: string, worktree: number, branch: string) => void
    cardSeparatorProvider: () => CardSeparator
    clearCardBranch: (path: string) => void
    flushPendingChanges: () => Promise<void>
    projectFolderProvider: () => string
    projectProvider: () => ProjectReference | null
    snapshotProvider: () => ProjectSnapshot | null
    storageProvider: () => StorageService | null
    unassignCardWorktree: (path: string) => void
}

/** Same outgoing-status condition used by worktree integration and diff controls. */
export function isWorktreeIntegratable(record: WorktreeRecord | null | undefined) {
    return !!record?.valid && (record.status.dirty || record.status.baseAhead > 0)
}

export class WorktreeService extends EventTarget {
    private adding = false
    private assignCardWorktreeValue: ((path: string, worktree: number, branch: string) => void) | null = null
    private cardSeparatorProvider: (() => CardSeparator) | null = null
    private clearCardBranchValue: ((path: string) => void) | null = null
    private error: string | null = null
    private flushPendingChanges: (() => Promise<void>) | null = null
    private pendingAssignments = new Map<number, string>()
    private preparingCardPaths = new Set<string>()
    private preparingProjectWorktree = false
    private projectActionWorktree: number | null = null
    private primaryStatus: WorktreeStatus | null = null
    private projectFolderProvider: (() => string) | null = null
    private projectProvider: (() => ProjectReference | null) | null = null
    private records: WorktreeRecord[] = []
    private snapshotProvider: (() => ProjectSnapshot | null) | null = null
    private storageProvider: (() => StorageService | null) | null = null
    private subscriptionCleanup: (() => void) | null = null
    private unassignCardWorktreeValue: ((path: string) => void) | null = null

    constructor() {
        super()
        register('worktreeService', this)
    }

    getRecords() {
        return this.records
    }

    getProjectActionWorktree() {
        return this.projectActionWorktree
    }

    getPrimaryStatus() {
        return this.primaryStatus
    }

    /** The branch linked worktrees are rebased onto; null before a project is open. */
    getProjectBranch() {
        return this.projectProvider?.()?.branch ?? null
    }

    getError() {
        return this.error
    }

    isAdding() {
        return this.adding
    }

    isPreparingCard(path: string) {
        return this.preparingCardPaths.has(path)
    }

    isPreparingProjectWorktree() {
        return this.preparingProjectWorktree
    }

    isWorktreeAvailableForCard(worktree: number, cardPath: string) {
        const pendingOwner = this.pendingAssignments.get(worktree)
        if (pendingOwner && pendingOwner !== cardPath) return false

        return !this.activeCards().some((card) => card.path !== cardPath && card.header.worktree === worktree)
    }

    /** Whether card has same valid outgoing worktree state required by integration. */
    canIntegrateCardWorktree(path: string) {
        const card = this.findCard(path)
        const worktree = card?.header.worktree
        if (!Number.isInteger(worktree) || !worktree || worktree <= 0 || card?.header.worktreeError) return false
        const record = this.records[worktree - 1]

        return isWorktreeIntegratable(record)
    }

    /** Load current diff for card's assigned worktree without changing operation state. */
    async generateCardWorktreeDiff(path: string): Promise<WorktreeDiffResult> {
        const { worktree } = this.requireCardOperation(path)
        if (!this.canIntegrateCardWorktree(path)) throw new Error('Card worktree has no changes to integrate')
        const bridge = getElectronActionBridge()
        if (!bridge?.generateWorktreeDiff) throw new Error('Worktree diff requires Electron local mode')

        return bridge.generateWorktreeDiff({ worktree })
    }

    /** Whether the active storage backend can list worktrees (local desktop or a remote-controlled desktop). */
    isSupported() {
        return !!this.storageProvider?.()?.onWorktreesChanged
    }

    init(dependencies: WorktreeServiceDependencies) {
        this.subscriptionCleanup?.()
        this.assignCardWorktreeValue = dependencies.assignCardWorktree
        this.cardSeparatorProvider = dependencies.cardSeparatorProvider
        this.clearCardBranchValue = dependencies.clearCardBranch
        this.flushPendingChanges = dependencies.flushPendingChanges
        this.projectFolderProvider = dependencies.projectFolderProvider
        this.projectProvider = dependencies.projectProvider
        this.snapshotProvider = dependencies.snapshotProvider
        this.storageProvider = dependencies.storageProvider
        this.unassignCardWorktreeValue = dependencies.unassignCardWorktree
        this.clear()
        this.subscriptionCleanup = dependencies.storageProvider()?.onWorktreesChanged?.((state) => this.handleState(state)) ?? null
    }

    clear() {
        this.projectActionWorktree = null
        this.primaryStatus = null
        this.error = null
        this.records = []
        this.dispatchChanged()
    }

    setProjectActionWorktree(worktree: number | null) {
        if (worktree !== null) {
            if (!Number.isInteger(worktree) || worktree <= 0) throw new Error(`Invalid project worktree index: ${String(worktree)}`)
            const record = this.records[worktree - 1]
            if (!record) throw new Error(`Configured worktree ${worktree} does not exist`)
            if (!record.valid) throw new Error(`Configured worktree ${worktree} is invalid: ${record.error}`)
        }
        if (this.projectActionWorktree === worktree) return

        this.projectActionWorktree = worktree
        this.dispatchChanged()
    }

    async setCardWorktree(path: string, worktree: number | null) {
        const card = this.requireCard(path)
        if (card.header.worktree === worktree && !card.header.worktreeError) return
        if (this.preparingCardPaths.has(path)) throw new Error(`Worktree preparation is already in progress for ${path}`)

        if (worktree === null) {
            if (card.header.worktreeError || card.header.worktree === null || card.header.worktree === undefined) {
                this.requireUnassignmentWriter()(path)
                return
            }

            const storage = this.requireStorage()
            if (!storage.parkWorktree) throw new Error('Worktree parking requires Electron local mode')
            const project = this.requireProject()
            this.startCardOperation(path)
            try {
                await storage.parkWorktree({ project, worktree: card.header.worktree })
                this.requireUnassignmentWriter()(path)
            } finally {
                this.finishCardOperation(path)
            }

            return
        }

        this.requireValidRecord(worktree)
        if (!this.isWorktreeAvailableForCard(worktree, path)) throw new Error(`Worktree ${worktree} is already assigned to another active card`)

        const storage = this.requireStorage()
        if (!storage.prepareWorktree) throw new Error('Worktree preparation requires Electron local mode')
        const project = this.requireProject()
        const branchName = slugifyTitle(`${card.header.id}-${card.header.title}`, this.requireCardSeparator())
        const request = { branchName, project, worktree }
        this.pendingAssignments.set(worktree, path)
        this.startCardOperation(path)
        try {
            await storage.prepareWorktree(request)
            if (this.requireProject() !== project) throw new Error('Opened project changed during worktree preparation')

            this.requireAssignmentWriter()(path, worktree, branchName)
        } finally {
            this.pendingAssignments.delete(worktree)
            this.finishCardOperation(path)
        }
    }

    async refresh() {
        const storage = this.requireStorage()
        const project = this.requireProject()
        if (!storage.refreshWorktrees) throw new Error('Refreshing worktrees requires Electron local mode')
        await storage.refreshWorktrees(project)
    }

    getCardCommitMessage(path: string) {
        const card = this.requireCard(path)

        return `${card.header.id}: ${card.header.title}`
    }

    async commitCardWorktree(path: string, message: string) {
        const { project, storage, worktree } = this.requireCardOperation(path)
        if (!storage.commitWorktree) throw new Error('Worktree commits require Electron local mode')

        this.startCardOperation(path)
        try {
            await storage.commitWorktree({ message, project, worktree })
        } finally {
            this.finishCardOperation(path)
        }
    }

    async integrateCardWorktree(path: string, deleteBranch: boolean) {
        const { card, project, storage, worktree } = this.requireCardOperation(path)
        if (!storage.integrateWorktree) throw new Error('Worktree integration requires Electron local mode')
        if (!card.header.internalId) throw new Error(`Cannot integrate card without an internal ID: ${path}`)
        const branch = card.header.branch
        if (deleteBranch && !branch) throw new Error(`Cannot delete branch without stored branch identity: ${path}`)
        const projectFolder = this.requireProjectFolder()

        this.startCardOperation(path)
        try {
            await this.requirePendingChangesFlusher()()
            const request = {
                ...(branch ? { branchName: branch } : {}),
                cardInternalId: card.header.internalId,
                deleteBranch,
                project,
                projectFolder,
                worktree,
            }
            const outcome = await storage.integrateWorktree(request)
            if (outcome.status === 'completed' && deleteBranch) {
                this.requireUnassignmentWriter()(path)
                this.requireBranchClearer()(path)
            }

            return outcome
        } finally {
            this.finishCardOperation(path)
        }
    }

    async updateCardWorktree(path: string) {
        const { project, storage, worktree } = this.requireCardOperation(path)
        if (!storage.rebaseWorktree) throw new Error('Worktree updates require Electron local mode')

        this.startCardOperation(path)
        try {
            await this.requirePendingChangesFlusher()()
            const outcome = await storage.rebaseWorktree({ project, worktree })

            return outcome
        } finally {
            this.finishCardOperation(path)
        }
    }

    getProjectCommitMessage() {
        return `Update ${this.getProjectBranch() ?? 'worktree'}`
    }

    async commitProjectWorktree(message: string) {
        const { project, storage, worktree } = this.requireProjectOperation()
        if (!storage.commitWorktree) throw new Error('Worktree commits require Electron local mode')

        this.startProjectOperation()
        try {
            await storage.commitWorktree({ message, project, worktree })
        } finally {
            this.finishProjectOperation()
        }
    }

    async integrateProjectWorktree() {
        const { project, storage, worktree } = this.requireProjectOperation()
        if (!storage.integrateWorktree) throw new Error('Worktree integration requires Electron local mode')

        this.startProjectOperation()
        try {
            await this.requirePendingChangesFlusher()()
            const outcome = await storage.integrateWorktree({ project, worktree })

            return outcome
        } finally {
            this.finishProjectOperation()
        }
    }

    async updateProjectWorktree() {
        const { project, storage, worktree } = this.requireProjectOperation()
        if (!storage.rebaseWorktree) throw new Error('Worktree updates require Electron local mode')

        this.startProjectOperation()
        try {
            await this.requirePendingChangesFlusher()()
            const outcome = await storage.rebaseWorktree({ project, worktree })

            return outcome
        } finally {
            this.finishProjectOperation()
        }
    }

    async discardAndUnassignCardWorktree(path: string) {
        const { project, storage, worktree } = this.requireCardOperation(path)
        if (!storage.discardWorktreeChanges) throw new Error('Discarding worktree changes requires Electron local mode')
        if (!storage.parkWorktree) throw new Error('Worktree parking requires Electron local mode')

        this.startCardOperation(path)
        try {
            await storage.discardWorktreeChanges({ project, worktree })
            await storage.parkWorktree({ project, worktree })
            this.requireUnassignmentWriter()(path)
        } finally {
            this.finishCardOperation(path)
        }
    }

    async add() {
        const storage = this.requireStorage()
        const project = this.requireProject()
        if (!storage.addWorktree) throw new Error('Worktree creation requires Electron local mode')
        if (this.adding) throw new Error('Worktree creation is already in progress')

        this.adding = true
        this.dispatchChanged()
        try {
            const added = await storage.addWorktree(project)

            return added
        } finally {
            this.adding = false
            this.dispatchChanged()
        }
    }

    async remove(index: number) {
        const storage = this.requireStorage()
        const project = this.requireProject()
        if (!storage.removeWorktree) throw new Error('Worktree removal requires Electron local mode')
        if (!Number.isInteger(index) || index < 0 || index >= this.records.length) throw new Error(`Invalid worktree list index: ${index}`)

        await storage.removeWorktree(project, this.records[index].path)
    }

    private requireProject() {
        const project = this.projectProvider?.()
        if (!project) throw new Error('Cannot save worktrees before a project is open')

        return project
    }

    private handleState(state: WorktreeState) {
        const project = this.projectProvider?.()
        if (!project || !state.project || project.id !== state.project.id || project.branch !== state.project.branch) return
        const recordsChanged = JSON.stringify(this.records) !== JSON.stringify(state.records)
        const primaryStatusChanged = JSON.stringify(this.primaryStatus) !== JSON.stringify(state.primaryStatus)
        if (!recordsChanged && !primaryStatusChanged && this.error === state.error) return

        if (recordsChanged) this.records = state.records
        if (primaryStatusChanged) this.primaryStatus = state.primaryStatus
        this.error = state.error
        this.dispatchChanged()
    }

    private activeCards() {
        return this.snapshotProvider?.()?.activeCards ?? []
    }

    private startCardOperation(path: string) {
        if (this.preparingCardPaths.has(path)) throw new Error(`Worktree operation is already in progress for ${path}`)

        this.preparingCardPaths.add(path)
        this.dispatchChanged()
    }

    private finishCardOperation(path: string) {
        this.preparingCardPaths.delete(path)
        this.dispatchChanged()
    }

    private requireCardOperation(path: string) {
        const card = this.requireCard(path)
        const snapshot = this.snapshotProvider?.()
        if (!snapshot) throw new Error('Worktree project snapshot is not initialized')
        const worktree = card.header.worktree
        if (!Number.isInteger(worktree) || !worktree || worktree <= 0) throw new Error(`Card has no valid worktree assignment: ${path}`)

        this.requireValidRecord(worktree)

        return { card, project: this.requireProject(), storage: this.requireStorage(), worktree }
    }

    private startProjectOperation() {
        if (this.preparingProjectWorktree) throw new Error('Worktree operation is already in progress for the project')

        this.preparingProjectWorktree = true
        this.dispatchChanged()
    }

    private finishProjectOperation() {
        this.preparingProjectWorktree = false
        this.dispatchChanged()
    }

    private requireProjectOperation() {
        const worktree = this.projectActionWorktree
        if (!Number.isInteger(worktree) || !worktree || worktree <= 0) throw new Error('No worktree is assigned to the project')

        this.requireValidRecord(worktree)

        return { project: this.requireProject(), storage: this.requireStorage(), worktree }
    }

    private requireAssignmentWriter() {
        if (!this.assignCardWorktreeValue) throw new Error('Worktree card assignment is not initialized')

        return this.assignCardWorktreeValue
    }

    private requireBranchClearer() {
        if (!this.clearCardBranchValue) throw new Error('Worktree card branch cleanup is not initialized')

        return this.clearCardBranchValue
    }

    private requireUnassignmentWriter() {
        if (!this.unassignCardWorktreeValue) throw new Error('Worktree card unassignment is not initialized')

        return this.unassignCardWorktreeValue
    }

    private requireProjectFolder() {
        const projectFolder = this.projectFolderProvider?.()
        if (typeof projectFolder !== 'string') throw new Error('Worktree project folder is not initialized')

        return projectFolder
    }

    private requireCard(path: string): Card {
        const card = this.findCard(path)
        if (!card) throw new Error(`Cannot assign a worktree to an unknown card: ${path}`)

        return card
    }

    private findCard(path: string) {
        const snapshot = this.snapshotProvider?.()
        const cards = [...(snapshot?.activeCards ?? []), ...(snapshot?.backgroundCards ?? [])]

        return cards.find((candidate) => candidate.path === path)
    }

    private requireCardSeparator() {
        const cardSeparator = this.cardSeparatorProvider?.()
        if (!cardSeparator) throw new Error('Worktree card separator is not initialized')

        return cardSeparator
    }

    private requireValidRecord(worktree: number) {
        if (!Number.isInteger(worktree) || worktree <= 0) throw new Error(`Invalid card worktree index: ${String(worktree)}`)
        const record = this.records[worktree - 1]
        if (!record) throw new Error(`Configured worktree ${worktree} does not exist`)
        if (!record.valid) throw new Error(`Configured worktree ${worktree} is invalid: ${record.error}`)

        return record
    }

    private requireStorage() {
        const storage = this.storageProvider?.()
        if (!storage) throw new Error('Worktree service storage is not initialized')

        return storage
    }

    private requirePendingChangesFlusher() {
        if (!this.flushPendingChanges) throw new Error('Worktree pending-change flusher is not initialized')

        return this.flushPendingChanges
    }

    private dispatchChanged() {
        this.dispatchEvent(new CustomEvent('changed'))
    }
}

export const worktreeService = new WorktreeService()

import { useSyncExternalStore } from 'react'
import { worktreeService } from '../../services/project/worktree_service'

function subscribe(onStoreChange: () => void) {
    worktreeService.addEventListener('changed', onStoreChange)

    return () => worktreeService.removeEventListener('changed', onStoreChange)
}

export function useWorktrees() {
    return useSyncExternalStore(subscribe, () => worktreeService.getRecords())
}

export function useProjectActionWorktree() {
    return useSyncExternalStore(subscribe, () => worktreeService.getProjectActionWorktree())
}

export function usePrimaryWorktreeStatus() {
    return useSyncExternalStore(subscribe, () => worktreeService.getPrimaryStatus())
}

export function useWorktreeAdding() {
    return useSyncExternalStore(subscribe, () => worktreeService.isAdding())
}


import type { ActionFile } from '../../data/action_types'
import type { ActionSchedule } from '../../data/action_schedule_types'
import type {
    BranchReference,
    CommitWorktreeRequest,
    CommitResult,
    CommitRequest,
    DeleteFileRequest,
    DeleteFolderRequest,
    AgentConversation,
    IntegrateWorktreeRequest,
    MoveFilesRequest,
    PrepareWorktreeRequest,
    ProjectConfig,
    ProjectReference,
    RepositoryReference,
    ProjectWatchEvent,
    ProjectWatchNotification,
    StorageProjectFiles,
    StorageService,
    TopLevelFolderReference,
    WorktreeOperationRequest,
    WorktreeState,
} from '../../data/data_types'
import { getElectronDataBridge, type ElectronDataBridge } from '../../data/electron_data_bridge'
import type {
    MergeConflictPathRequest,
    MergeConflictSession,
    MergeConflictSessionRequest,
    WorktreeOperationOutcome,
} from '../../data/merge_conflict_types'

interface LocalGitStorageDependencies {
    bridge?: ElectronDataBridge
}

export class LocalGitStorageService implements StorageService {
    private bridge: ElectronDataBridge | null
    private readonly pendingPushBranches: Set<string>

    constructor() {
        this.bridge = null
        this.pendingPushBranches = new Set()
    }

    async addWorktree(project: ProjectReference): Promise<boolean> {
        const bridge = this.requireBridge()
        if (!bridge.addWorktree) throw new Error('Electron local Git bridge cannot add worktrees')

        return bridge.addWorktree(project)
    }

    init(dependencies: LocalGitStorageDependencies = {}) {
        const bridge = dependencies.bridge ?? getElectronDataBridge()

        if (!bridge) throw new Error('Electron local Git bridge is not available')

        this.bridge = bridge
    }

    async openProjectFolder() {
        return this.requireBridge().openProjectFolder()
    }

    async resolveProject(project: ProjectReference) {
        return this.requireBridge().resolveProject(project)
    }

    async createProject(project: ProjectReference, workingFolder: string): Promise<ProjectReference> {
        return this.requireBridge().createProject(project, workingFolder)
    }

    async loadProject(project: ProjectReference, workingFolder: string): Promise<StorageProjectFiles> {
        return this.requireBridge().loadProject(project, workingFolder)
    }

    async loadFile(project: ProjectReference, path: string) {
        return this.requireBridge().loadFile(project, path)
    }

    async loadProjectAsset(project: ProjectReference, path: string) {
        const bridge = this.requireBridge()
        if (!bridge.loadProjectAsset) throw new Error('Electron local Git bridge cannot load project assets')

        return bridge.loadProjectAsset(project, path)
    }

    async loadTextFile(project: ProjectReference, path: string) {
        const bridge = this.requireBridge()
        if (!bridge.loadTextFile) throw new Error('Electron local Git bridge cannot load text files')

        return bridge.loadTextFile(project, path)
    }

    async loadProjectRoot(project: ProjectReference, workingFolder: string): Promise<StorageProjectFiles> {
        return this.requireBridge().loadProjectRoot(project, workingFolder)
    }

    async loadActionFiles(project: ProjectReference, actionsFolder: string): Promise<ActionFile[]> {
        return this.requireBridge().loadActionFiles(project, actionsFolder)
    }

    async loadActionSchedules(project: ProjectReference, actionsFolder: string): Promise<ActionSchedule[]> {
        const bridge = this.requireBridge()
        if (!bridge.loadActionSchedules) throw new Error('Electron local Git bridge cannot load action schedules')

        return bridge.loadActionSchedules(project, actionsFolder)
    }

    async saveActionSchedules(project: ProjectReference, actionsFolder: string, schedules: ActionSchedule[]): Promise<ActionSchedule[]> {
        const bridge = this.requireBridge()
        if (!bridge.saveActionSchedules) throw new Error('Electron local Git bridge cannot save action schedules')

        return bridge.saveActionSchedules(project, actionsFolder, schedules)
    }

    async cancelActionSchedule(project: ProjectReference, actionsFolder: string, scheduleId: string): Promise<ActionSchedule[]> {
        const bridge = this.requireBridge()
        if (!bridge.cancelActionSchedule) throw new Error('Electron local Git bridge cannot cancel action schedules')

        return bridge.cancelActionSchedule(project, actionsFolder, scheduleId)
    }

    async loadAgentConversation(_project: ProjectReference, path: string): Promise<AgentConversation> {
        const bridge = this.requireBridge()
        if (!bridge.loadAgentConversation) throw new Error('Electron local Git bridge cannot load agent conversations')

        return bridge.loadAgentConversation(path)
    }

    async stopAgent(_project: ProjectReference, runId: string): Promise<void> {
        const bridge = this.requireBridge()
        if (!bridge.stopAgent) throw new Error('Electron local Git bridge cannot stop agents')

        await bridge.stopAgent(runId)
    }

    async loadProjectConfig(project: ProjectReference): Promise<Partial<ProjectConfig> | null> {
        return this.requireBridge().loadProjectConfig(project)
    }

    onWorktreesChanged(callback: (state: WorktreeState) => void) {
        const bridge = this.requireBridge()
        if (!bridge.onWorktreesChanged) throw new Error('Electron local Git bridge cannot subscribe to worktrees')

        return bridge.onWorktreesChanged(callback)
    }

    async listBranches(project: ProjectReference): Promise<BranchReference[]> {
        return this.requireBridge().listBranches(project)
    }

    async listRepositories(): Promise<RepositoryReference[]> {
        this.requireBridge()

        return []
    }

    async listRepositoryFiles(project: ProjectReference): Promise<string[]> {
        return this.requireBridge().listRepositoryFiles(project)
    }

    async listAgentConversationReferences(project: ProjectReference, projectFolder: string): Promise<string[]> {
        const bridge = this.requireBridge()
        if (!bridge.listAgentConversationReferences) throw new Error('Electron local Git bridge cannot list agent conversations')

        return bridge.listAgentConversationReferences(project, projectFolder)
    }

    async listTopLevelFolders(project: ProjectReference): Promise<TopLevelFolderReference[]> {
        return this.requireBridge().listTopLevelFolders(project)
    }

    async loadPendingPush(project: ProjectReference) {
        const hasPendingPush = await this.requireBridge().hasPendingPush(project)
        if (hasPendingPush) this.pendingPushBranches.add(project.branch)
        else this.pendingPushBranches.delete(project.branch)
    }

    async integrateWorktree(request: IntegrateWorktreeRequest): Promise<WorktreeOperationOutcome> {
        const bridge = this.requireBridge()
        if (!bridge.integrateWorktree) throw new Error('Electron local Git bridge cannot integrate worktrees')

        const outcome = await bridge.integrateWorktree(request)
        this.pendingPushBranches.add(request.project.branch)

        return outcome
    }

    async abortMergeConflict(request: MergeConflictSessionRequest): Promise<void> {
        const bridge = this.requireBridge()
        if (!bridge.abortMergeConflict) throw new Error('Electron local Git bridge cannot abort merge conflicts')

        await bridge.abortMergeConflict(request)
    }

    async continueMergeConflict(request: MergeConflictSessionRequest): Promise<WorktreeOperationOutcome> {
        const bridge = this.requireBridge()
        if (!bridge.continueMergeConflict) throw new Error('Electron local Git bridge cannot continue merge conflicts')

        return bridge.continueMergeConflict(request)
    }

    async getMergeConflictSession(): Promise<MergeConflictSession | null> {
        const bridge = this.requireBridge()
        if (!bridge.getMergeConflictSession) throw new Error('Electron local Git bridge cannot load merge conflicts')

        return bridge.getMergeConflictSession()
    }

    async launchMergeConflictResolver(request: MergeConflictPathRequest): Promise<void> {
        const bridge = this.requireBridge()
        if (!bridge.launchMergeConflictResolver) throw new Error('Electron local Git bridge cannot launch merge conflict resolver')

        await bridge.launchMergeConflictResolver(request)
    }

    async markMergeConflictResolved(request: MergeConflictPathRequest): Promise<MergeConflictSession> {
        const bridge = this.requireBridge()
        if (!bridge.markMergeConflictResolved) throw new Error('Electron local Git bridge cannot mark merge conflicts resolved')

        return bridge.markMergeConflictResolved(request)
    }

    onMergeConflictSessionChanged(callback: (session: MergeConflictSession | null) => void) {
        const bridge = this.requireBridge()
        if (!bridge.onMergeConflictSessionChanged) throw new Error('Electron local Git bridge cannot subscribe to merge conflicts')

        return bridge.onMergeConflictSessionChanged(callback)
    }

    async rescanMergeConflict(request: MergeConflictSessionRequest): Promise<MergeConflictSession> {
        const bridge = this.requireBridge()
        if (!bridge.rescanMergeConflict) throw new Error('Electron local Git bridge cannot rescan merge conflicts')

        return bridge.rescanMergeConflict(request)
    }

    async checkoutBranch(project: ProjectReference, branch: string): Promise<ProjectReference> {
        return this.requireBridge().checkoutBranch(project, branch)
    }

    async commit(request: CommitRequest): Promise<CommitResult> {
        await this.requireBridge().commit(request)
        this.pendingPushBranches.add(request.branch)

        return []
    }

    async commitWorktree(request: CommitWorktreeRequest): Promise<void> {
        const bridge = this.requireBridge()
        if (!bridge.commitWorktree) throw new Error('Electron local Git bridge cannot commit worktree changes')

        await bridge.commitWorktree(request)
    }

    async deleteFile(request: DeleteFileRequest): Promise<void> {
        await this.requireBridge().deleteFile(request)
        this.pendingPushBranches.add(request.branch)
    }

    async deleteFolder(request: DeleteFolderRequest): Promise<void> {
        await this.requireBridge().deleteFolder(request)
        this.pendingPushBranches.add(request.branch)
    }

    async deleteLocalBranch(project: ProjectReference, branchName: string): Promise<void> {
        const bridge = this.requireBridge()
        if (!bridge.deleteLocalBranch) throw new Error('Electron local Git bridge cannot delete local branches')

        await bridge.deleteLocalBranch(project, branchName)
    }

    async discardWorktreeChanges(request: WorktreeOperationRequest): Promise<void> {
        const bridge = this.requireBridge()
        if (!bridge.discardWorktreeChanges) throw new Error('Electron local Git bridge cannot discard worktree changes')

        await bridge.discardWorktreeChanges(request)
    }

    async moveFiles(request: MoveFilesRequest): Promise<void> {
        await this.requireBridge().moveFiles(request)
        this.pendingPushBranches.add(request.branch)
    }

    async push(project: ProjectReference): Promise<void> {
        await this.requireBridge().push(project)
        this.pendingPushBranches.delete(project.branch)
    }

    async pull(project: ProjectReference): Promise<void> {
        const bridge = this.requireBridge()
        if (!bridge.pull) throw new Error('Electron local Git bridge cannot pull the primary worktree')

        await bridge.pull(project)
    }

    async prepareWorktree(request: PrepareWorktreeRequest): Promise<void> {
        const bridge = this.requireBridge()
        if (!bridge.prepareWorktree) throw new Error('Electron local Git bridge cannot prepare worktrees')

        await bridge.prepareWorktree(request)
    }

    async parkWorktree(request: WorktreeOperationRequest): Promise<void> {
        const bridge = this.requireBridge()
        if (!bridge.parkWorktree) throw new Error('Electron local Git bridge cannot park worktrees')

        await bridge.parkWorktree(request)
    }

    async pullWorktree(request: WorktreeOperationRequest): Promise<void> {
        const bridge = this.requireBridge()
        if (!bridge.pullWorktree) throw new Error('Electron local Git bridge cannot pull worktrees')

        await bridge.pullWorktree(request)
    }

    async rebaseWorktree(request: WorktreeOperationRequest): Promise<WorktreeOperationOutcome> {
        const bridge = this.requireBridge()
        if (!bridge.rebaseWorktree) throw new Error('Electron local Git bridge cannot rebase worktrees')

        return bridge.rebaseWorktree(request)
    }

    async pushWorktree(request: WorktreeOperationRequest): Promise<void> {
        const bridge = this.requireBridge()
        if (!bridge.pushWorktree) throw new Error('Electron local Git bridge cannot push worktrees')

        await bridge.pushWorktree(request)
    }

    async refreshWorktrees(project: ProjectReference): Promise<void> {
        const bridge = this.requireBridge()
        if (!bridge.refreshWorktrees) throw new Error('Electron local Git bridge cannot refresh worktrees')

        await bridge.refreshWorktrees(project)
    }

    async saveProjectConfig(project: ProjectReference, config: ProjectConfig): Promise<void> {
        await this.requireBridge().saveProjectConfig(project, config)
        this.pendingPushBranches.add(project.branch)
    }

    async removeWorktree(project: ProjectReference, folderPath: string): Promise<void> {
        const bridge = this.requireBridge()
        if (!bridge.removeWorktree) throw new Error('Electron local Git bridge cannot remove worktrees')

        await bridge.removeWorktree(project, folderPath)
    }

    hasPendingPush(project: ProjectReference) {
        return this.pendingPushBranches.has(project.branch)
    }

    watchProject(
        project: ProjectReference,
        onChange: (event: ProjectWatchEvent) => void,
        _onRestored: () => void,
        onError: (error: Error) => void,
    ) {
        const handleNotification = (notification: ProjectWatchNotification) => {
            if ('error' in notification) {
                onError(new Error(notification.error))
                return
            }

            onChange(notification)
        }

        return this.requireBridge().watchProject(project, handleNotification)
    }

    private requireBridge() {
        if (!this.bridge) throw new Error('Local Git storage bridge is not initialized')

        return this.bridge
    }
}

